docs/specs/schemas/rulith-agent-mcp-meta.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-agent-mcp-meta-v4.schema.json",
  "title": "Rulith MCP metadata and recent-operations strip (rulith/v4)",
  "description": "The root is the Host-only _meta[\"rulith/v4\"] block of tools/call results and of initialize and ping results (tools/list results use it too when they carry _meta); progress notifications carry ProgressMeta instead. Gateway output only, never a model tool input. Session identity comes from the authenticated Mcp-Session-Id header. $defs also define the model-visible recent-operations strip, carried as `operations` in the decoded text of every tools/call result, the held-call and pre-execution refusal result forms, and the Host-only held-call references in progress notifications and replacement errors. There is no recovery object, operation target, callRef or operation-read tool: the Gateway holds each call until its outcome, a human decision or the hold bound, and an outcome reaches the model through the strip of any later tool result. The optional client declaration is a compatibility signal, not authority; ordinary tools-only MCP Hosts need no capability. Package A (D-1008i): this metadata speaks of goals only; focusedGoals and affectedGoals name top-level goals, and the Case stays the word of the Core record, receipts and Console.",
  "type": "object",
  "additionalProperties": false,
  "required": ["agentId", "focusedGoals"],
  "properties": {
    "agentId": { "type": "string", "minLength": 1 },
    "focusedGoals": {
      "type": "array",
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 },
      "description": "Package A (D-1008i), formerly focusedRoots: the top-level goal IDs this session is focused on, as the authority reported them. A Host never derives focus itself; an ID the authority did not return is not focus."
    },
    "boardRevision": { "type": "string", "minLength": 1 },
    "affectedGoals": {
      "type": "array",
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 },
      "description": "Package A (D-1008i), formerly affectedCases: complete authoritative top-level goal IDs, not sub-goal IDs; absent for results that do not report a graph write. Never truncate silently."
    },
    "operations": {
      "$ref": "#/$defs/OperationsStripState",
      "description": "Present in initialize and ping results: the state-only form of the same Agent strip, with each entry's Host-only ordinal. Published for any Host that reads _meta; it is not a first-party channel. It never delivers a result."
    }
  },
  "$defs": {
    "ToolName": {
      "type": "string",
      "enum": ["Get", "Set", "Execute"],
      "description": "Package A (D-1008i): exactly the three v4 tools (D-1012g; D-1012a: EndGoal became the ApplyBatch operation end_goal). OpenCase and CloseCase are not model tools."
    },
    "OperationTool": {
      "type": "string",
      "enum": ["Set", "Execute", "Get"],
      "description": "Tools whose calls the Gateway holds and records as operations. Get entries are Artifact reads only; a Get without artifact is never held and never becomes a strip entry."
    },
    "WriteTool": {
      "type": "string",
      "enum": ["Set", "Execute"]
    },
    "ClientCapabilities": {
      "type": "object",
      "additionalProperties": false,
      "minProperties": 1,
      "properties": { "heldCalls": { "const": 1 } },
      "description": "Optional declaration in initialize.capabilities.experimental[\"rulith/v4\"]. Only heldCalls:1 is accepted for new sessions (D-1013a); seat is refused as incompatible_client before a session is opened or replaced. Clients without a Rulith declaration still receive the current interface. heldCalls grants no execution, observation or result-claim right. Old namespace declarations remain incompatible."
    },
    "SeatName": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_-]{0,31}$",
      "description": "Historical only (D-1013a): name of a stored seat, retained for decoding original view results; new sessions and operations entries do not carry seat."
    },
    "ServerCapabilities": {
      "type": "object",
      "additionalProperties": false,
      "required": ["heldCalls"],
      "properties": { "heldCalls": { "const": 1 } },
      "description": "Server-advertised initialize capabilities.experimental[\"rulith/v4\"]. heldCalls:1 promises held calls, the recent-operations strip in every tool result and independent Get observation without artifact outside the execution slot. It is implementation support, not permission. A client need not echo it."
    },
    "OperationState": {
      "type": "string",
      "enum": ["running", "waiting_for_decision", "done", "failed", "refused", "unknown", "needs_person"],
      "description": "The outcome class of the Agent's own call, which is always shown. unknown is a reconciled business outcome whose external effect stays unknown; it is never a failure and never a transport or timing verdict. needs_person means reconciliation is required in Console. Only content can be withheld, never the state."
    },
    "RunningStage": {
      "type": "string",
      "enum": ["not_dispatched", "at_worker"]
    },
    "Timestamp": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,9})?Z$",
      "description": "RFC 3339 UTC time."
    },
    "Ordinal": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991,
      "description": "Host-only per-Agent operation ordinal, allocated by the Gateway in admission order, strictly increasing and never reused. It appears only in the _meta state form, in progress notifications and in connection_replaced error data, never in model-visible content. It is not a request identity, is accepted by no tool and grants nothing."
    },
    "Label": {
      "type": "string",
      "minLength": 1,
      "maxLength": 200,
      "description": "Model-readable and taken only from the call's own input: the tool, then the Action name, the goal the call named or the Artifact reference, then the public target when the call named one. So it never shows a server-minted identifier such as the ID of a goal the call declared, nor a request id, callRef, invocation, ordinal, Board or Agent identity."
    },
    "PublicToolResult": {
      "type": "object",
      "additionalProperties": false,
      "required": ["content", "isError"],
      "properties": {
        "content": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["type", "text"],
            "properties": {
              "type": { "const": "text" },
              "text": { "type": "string" }
            }
          }
        },
        "structuredContent": {
          "type": "object",
          "not": {
            "anyOf": [
              { "required": ["_meta"] },
              { "required": ["rawReceipt"] },
              { "required": ["agentId"] },
              { "required": ["boardId"] }
            ]
          },
          "description": "Present only when the original public result already disclosed this content. The Gateway projects nested content under the same current disclosure rules; this shallow exclusion is not an authorization filter or a second Board result schema."
        },
        "isError": { "type": "boolean" }
      },
      "description": "Exactly the public tool result the held call returned or would have returned, re-projected under current disclosure: its own answer without `operations`, _meta, raw Core or Worker receipts, local-delivery tickets, agentId, boardId or undisclosed business data. A nested business refusal keeps isError:true here; it does not make the carrying response an error."
    },
    "OperationEntry": {
      "type": "object",
      "additionalProperties": false,
      "required": ["tool", "label", "state", "at", "since"],
      "properties": {
        "tool": { "$ref": "#/$defs/OperationTool" },
        "label": { "$ref": "#/$defs/Label" },
        "state": { "$ref": "#/$defs/OperationState" },
        "stage": { "$ref": "#/$defs/RunningStage" },
        "decision": {
          "type": "string",
          "minLength": 1,
          "maxLength": 200,
          "description": "The kind of human decision awaited, at the disclosure level the product owner approves; the draft uses conservative text such as \"a person's decision in Console\". Never a role, grant, person or internal identity."
        },
        "reason": { "type": "string", "minLength": 1, "maxLength": 500 },
        "contentWithheld": {
          "const": true,
          "description": "The outcome class is shown, but its content (result, summary, reason and facts) may not be disclosed to this caller now, because disclosure is denied or cannot be determined now."
        },
        "at": { "$ref": "#/$defs/Timestamp", "description": "When the Gateway admitted the operation; strictly increasing within an Agent, so label and at tell entries apart." },
        "since": { "$ref": "#/$defs/Timestamp", "description": "When the operation entered its current state." },
        "result": { "$ref": "#/$defs/PublicToolResult" },
        "summary": {
          "type": "string",
          "minLength": 1,
          "maxLength": 500,
          "description": "Bounded one-line outcome under current disclosure. Never bytes, tickets or raw receipts."
        }
      },
      "allOf": [
        {
          "if": { "properties": { "state": { "const": "running" } }, "required": ["state"] },
          "else": { "not": { "required": ["stage"] } }
        },
        {
          "if": { "properties": { "state": { "const": "waiting_for_decision" } }, "required": ["state"] },
          "then": { "required": ["decision"] },
          "else": { "not": { "required": ["decision"] } }
        },
        {
          "if": { "required": ["contentWithheld"] },
          "then": {
            "properties": { "state": { "enum": ["done", "failed", "refused", "unknown"] } },
            "not": { "anyOf": [ { "required": ["result"] }, { "required": ["summary"] }, { "required": ["reason"] } ] }
          },
          "else": {
            "allOf": [
              {
                "if": { "properties": { "state": { "const": "refused" } }, "required": ["state"] },
                "then": { "required": ["reason"] },
                "else": { "not": { "required": ["reason"] } }
              },
              {
                "if": { "properties": { "state": { "enum": ["done", "failed", "refused", "unknown"] } }, "required": ["state"] },
                "then": { "oneOf": [ { "required": ["result"] }, { "required": ["summary"] } ] },
                "else": { "not": { "anyOf": [ { "required": ["result"] }, { "required": ["summary"] } ] } }
              }
            ]
          }
        },
        {
          "if": { "properties": { "tool": { "const": "Get" } }, "required": ["tool"] },
          "then": { "not": { "required": ["result"] } }
        }
      ],
      "description": "One operation of this Agent, without the Host-only ordinal. The outcome class is always shown. done, failed, refused and unknown entries carry exactly one of `result` or `summary`, and refused also `reason`, unless `contentWithheld` is set, in which case none of them. Only the most recent determined write (Set or Execute) carries `result`, and only while that result is unacknowledged, without time limit; a previous_result_undelivered refusal always carries it. After acknowledgement the entry carries `summary` and stays in the strip for 24 hours. In the response that is itself that operation's result its entry carries `summary`, because the response is the result. A replay of the same RPC carries again in full every entry its original response carried in full, subject to the current disclosure re-check (otherwise contentWithheld) and only within retention. Get artifact entries never carry `result`, bytes or tickets: a lost read is re-issued as a new read."
    },
    "OperationsStrip": {
      "type": "array",
      "maxItems": 7,
      "items": { "$ref": "#/$defs/OperationEntry" },
      "description": "Agent-scoped, newest first, only operations that still need attention (D-1012e): the Agent's unresolved operation and its most recent determined write while its result is unacknowledged; empty when there are none (single session line restored by D-1013a). Delivered means a tools/call result carrying the full result, or its outcome class with contentWithheld, was written to a session. Only the answer of a held call (an admitted Set, Execute or Get with artifact) can be voided: a notifications/cancelled for that held call arriving before the delivery is acknowledged voids it, whenever it was sent. Pre-execution refusals and Get results without artifact answer immediately; a cancel for them is post-completion and is ignored, as MCP allows, so their delivery stands. Acknowledged means that session later received another JSON-RPC request that is not a replay, or the result has been delivered, uncancelled, to two distinct sessions of the same Agent. Present whether or not a goal is open, generated when each response is written, under current disclosure. It is part of the position, not another call, and never occupies an execution slot."
    },
    "OperationStateEntry": {
      "type": "object",
      "additionalProperties": false,
      "required": ["ordinal", "tool", "label", "state", "at", "since"],
      "properties": {
        "ordinal": { "$ref": "#/$defs/Ordinal" },
        "tool": { "$ref": "#/$defs/OperationTool" },
        "label": { "$ref": "#/$defs/Label" },
        "state": { "$ref": "#/$defs/OperationState" },
        "stage": { "$ref": "#/$defs/RunningStage" },
        "at": { "$ref": "#/$defs/Timestamp" },
        "since": { "$ref": "#/$defs/Timestamp" }
      },
      "allOf": [
        {
          "if": { "properties": { "state": { "const": "running" } }, "required": ["state"] },
          "else": { "not": { "required": ["stage"] } }
        }
      ],
      "description": "State-only, Host-only form: the ordinal plus state, but no result, summary, reason, decision text or content flag. Hosts map an ordinal to a model-visible entry by its label and at."
    },
    "OperationsStripState": {
      "type": "array",
      "maxItems": 7,
      "items": { "$ref": "#/$defs/OperationStateEntry" }
    },
    "DisclosureRefusalCode": {
      "type": "string",
      "enum": ["result_unavailable", "not_authorized", "audience_profile_required", "audience_profile_denied"],
      "description": "Refusals about disclosure or about the read's own authorization: the current disclosure of a saved snapshot, Board read authorization and the protected audience profile. They carry no view and return zero Board data."
    },
    "GateReason": {
      "type": "string",
      "enum": ["operation_running", "previous_result_undelivered"]
    },
    "PreExecutionRefusal": {
      "type": "object",
      "additionalProperties": false,
      "required": ["accepted", "requestExecuted", "tool", "errorCode", "teaching", "operations"],
      "properties": {
        "accepted": { "const": false },
        "requestExecuted": { "const": false },
        "tool": { "$ref": "#/$defs/OperationTool" },
        "errorCode": { "type": "string", "minLength": 1 },
        "teaching": { "type": "string", "minLength": 1 },
        "operations": { "$ref": "#/$defs/OperationsStrip" },
        "view": { "type": "object" }
      },
      "allOf": [
        {
          "if": { "properties": { "tool": { "const": "Get" } }, "required": ["tool"] },
          "then": {
            "if": { "properties": { "errorCode": { "$ref": "#/$defs/DisclosureRefusalCode" } }, "required": ["errorCode"] },
            "then": { "not": { "required": ["view"] } }
          },
          "else": {
            "if": { "properties": { "errorCode": { "$ref": "#/$defs/DisclosureRefusalCode" } }, "required": ["errorCode"] },
            "then": { "not": { "required": ["view"] } },
            "else": { "required": ["view"] }
          }
        },
        {
          "if": { "properties": { "errorCode": { "const": "previous_result_undelivered" } }, "required": ["errorCode"] },
          "then": {
            "properties": {
              "tool": { "$ref": "#/$defs/WriteTool" },
              "operations": {
                "contains": {
                  "properties": { "tool": { "$ref": "#/$defs/WriteTool" } },
                  "required": ["tool"],
                  "anyOf": [ { "required": ["result"] }, { "required": ["contentWithheld"] } ]
                }
              }
            }
          }
        }
      ],
      "description": "Decoded text of an ordinary tools/call result for a request that was not executed, such as the write gate's GateReason codes. It names the refused request's public tool. Get covers two routes: this result does not echo the input, so the Gateway enforces the route-specific view rule; the schema permits either form for non-disclosure Get refusals. It is not an operation and takes no ordinal, and it is never a JSON-RPC 409. A refusal of a Board tool (Set or Execute) carries the position, the strip and the bounded Board View (an unavailable view is still an object), unless it is a disclosure or read-authorization refusal; a refused Get with artifact carries no view, because Get with artifact does not read the Board. A previous_result_undelivered refusal always carries the latest determined write in full, or with its outcome class and contentWithheld, and so delivers it to the current session. A replay of the same RPC returns the same refusal and never turns into an execution."
    },
    "HeldCallResult": {
      "type": "object",
      "additionalProperties": false,
      "required": ["state", "operations"],
      "properties": {
        "state": { "$ref": "#/$defs/OperationState" },
        "contentWithheld": { "const": true },
        "teaching": { "type": "string", "minLength": 1 },
        "operations": { "$ref": "#/$defs/OperationsStrip" },
        "view": { "type": "object" }
      },
      "allOf": [
        {
          "if": { "properties": { "state": { "enum": ["done", "failed", "refused", "unknown"] } }, "required": ["state"] },
          "then": { "required": ["contentWithheld"] },
          "else": { "not": { "required": ["contentWithheld"] } }
        }
      ],
      "description": "Decoded text of a held call's own response when it ends without a disclosable outcome: running at the hold bound, waiting_for_decision or needs_person (both returned promptly), or a determined outcome class whose content is withheld from this caller now, which delivers that outcome class. Writes also carry the bounded Board View; Get with artifact does not read the Board. It carries no ordinal: a Host learns it from the first progress notification. A disclosable determined outcome is returned as the tool's ordinary result instead; unknown is never reported for transport or timing."
    },
    "ProgressMeta": {
      "type": "object",
      "additionalProperties": false,
      "required": ["ordinal"],
      "properties": { "ordinal": { "$ref": "#/$defs/Ordinal" } },
      "description": "params._meta[\"rulith/v4\"] of every notifications/progress for a held call; the first is sent right after admission when the request carries a progressToken."
    },
    "ConnectionReplacedHeldCall": {
      "type": "object",
      "additionalProperties": false,
      "required": ["reason", "ordinal"],
      "properties": {
        "reason": { "const": "connection_replaced" },
        "ordinal": { "$ref": "#/$defs/Ordinal" }
      },
      "description": "error.data of the JSON-RPC error that ends a held call's stream when its session is replaced, and of the HTTP 409 JSON-RPC error that answers a same-id retransmission of an already-admitted call arriving on a replaced session. The call was admitted and may have executed, so it carries its ordinal and never requestExecuted:false."
    },
    "ConnectionReplacedRequest": {
      "type": "object",
      "additionalProperties": false,
      "required": ["reason", "requestExecuted"],
      "properties": {
        "reason": { "const": "connection_replaced" },
        "requestExecuted": { "const": false }
      },
      "description": "error.data of the HTTP 409 JSON-RPC error that refuses a new request (tools/call, ping or another JSON-RPC request) on a replaced session; the request was not executed. A same-id retransmission of an already-admitted call is not a new request: it gets ConnectionReplacedHeldCall with the call's ordinal, never this shape."
    },
    "ConnectionReplacedStream": {
      "type": "object",
      "additionalProperties": false,
      "required": ["reason"],
      "properties": { "reason": { "const": "connection_replaced" } },
      "description": "error.data of the HTTP 409 JSON-RPC error (id null) that refuses a GET stream resumption on a replaced session; a resumption is not a request."
    },
    "ConnectionReplacedData": {
      "oneOf": [
        { "$ref": "#/$defs/ConnectionReplacedHeldCall" },
        { "$ref": "#/$defs/ConnectionReplacedRequest" },
        { "$ref": "#/$defs/ConnectionReplacedStream" }
      ],
      "description": "Every error.data shape that signals connection replacement."
    }
  }
}

docs/specs/schemas/rulith-artifact-read-.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-artifact-read-v1.schema.json",
  "title": "Immutable generated-result Artifact read contract",
  "description": "Gateway data-plane contract. Production ownership, Source off-machine/storage permission, current disclosure authorization and durable retention are checked separately; reading never creates a Case or changes Board state.",
  "$ref": "#/$defs/ReadArtifact",
  "$defs": {
    "ArtifactRef": {
      "type": "string",
      "pattern": "^art_[a-f0-9]{32}$",
      "description": "Service-minted opaque reference. Knowledge of it does not grant access; never a URL or filesystem path."
    },
    "ReadArtifact": {
      "type": "object",
      "description": "Bounded read of an Artifact a tool result supplied.",
      "additionalProperties": false,
      "required": [
        "ref"
      ],
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "offset": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991,
          "default": 0
        },
        "maxBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991,
          "description": "Requested upper bound; omission uses the configured read budget, larger requests are rejected rather than enlarging that budget."
        }
      }
    },
    "ReadArtifactResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ref",
        "mediaType",
        "encoding",
        "data",
        "offset",
        "nextOffset",
        "totalBytes",
        "complete",
        "truncated"
      ],
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "encoding": {
          "enum": [
            "utf8",
            "base64"
          ]
        },
        "data": {
          "type": "string"
        },
        "offset": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "nextOffset": {
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            {
              "type": "null"
            }
          ]
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "complete": {
          "type": "boolean"
        },
        "truncated": {
          "type": "boolean"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "complete": {
                "const": true
              }
            },
            "required": [
              "complete"
            ]
          },
          "then": {
            "properties": {
              "nextOffset": {
                "type": "null"
              },
              "truncated": {
                "const": false
              }
            }
          },
          "else": {
            "properties": {
              "nextOffset": {
                "type": "integer",
                "minimum": 0,
                "maximum": 9007199254740991
              },
              "truncated": {
                "const": true
              }
            }
          }
        }
      ],
      "description": "Offsets and totalBytes count the original immutable bytes; utf8 chunks never split a code point, binary data is base64. Completion means this read reached object EOF, not Case completion. The server also checks offset advancement and byte counts."
    },
    "ArtifactPolicy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "inlineBytes",
        "readBytes",
        "objectBytes",
        "totalBytes",
        "temporaryRetentionMs"
      ],
      "properties": {
        "inlineBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "readBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "objectBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "temporaryRetentionMs": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        }
      },
      "description": "Values are supplied by existing deployment/operator configuration. Source permission is independent; quotas do not grant off-machine storage or release retained data."
    },
    "ArtifactUpload": {
      "type": "object",
      "required": [
        "executionGrant",
        "mediaType",
        "digest",
        "payloadEncoding",
        "bytes"
      ],
      "additionalProperties": false,
      "description": "Private Worker upload on /work/artifact. bytes is canonical base64 transport encoding; digest covers decoded original bytes. Gateway derives ownership and actual Source from the current granted invocation, computes length, checks effective retention permission and budgets, and durably retains before returning a reference. No worker-supplied owner, Source, totalBytes or retained flag. Retry of the same producing invocation and digest returns the same immutable object reference; different bytes require a distinct reference under the same existing storage budgets. Empty/small results remain inline under policy. Producer wiring constraint: before any object byte leaves the producing machine the Worker must already hold an explicit authenticated off-machine permission from the actual Source record. Holding the bytes, knowing a Source name, or having reached the server is not that permission, and bytes already received are never treated as authorization. Gateway rechecks the current permission and the current lease before accepting and retaining, and refuses a missing permission by name rather than by a default policy lookup miss. The grant is signed with the authenticated Connection key, which the Worker also holds, so a valid signature proves only that this Connection wrote the token and is never on its own evidence that Core dispatched the invocation. Admission therefore starts from Core's own trusted dispatched record for that invocation, recomputes the request identity from the Source, Tool pin and lease in force now, requires it to equal the identity the grant states, and hashes the bytes actually received rather than trusting the declared digest. A mismatch is a named artifact_digest_mismatch refusal before deduplication, finalization, retention or reference return. The deduplication key uses the verified content digest, so a retry carrying different bytes cannot retrieve a prior reference by claiming its digest.",
      "properties": {
        "executionGrant": {
          "type": "string",
          "minLength": 1
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "digest": {
          "$ref": "#/$defs/Digest"
        },
        "payloadEncoding": {
          "const": "base64"
        },
        "bytes": {
          "type": "string",
          "pattern": "^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$",
          "minLength": 4
        }
      }
    },
    "ArtifactUploadResult": {
      "type": "object",
      "required": [
        "ref",
        "mediaType",
        "encoding",
        "totalBytes",
        "digest"
      ],
      "additionalProperties": false,
      "description": "Gateway-computed immutable object metadata. Reading encoding is separate from upload transport encoding. Invalid UTF8 must never be silently replaced; serve original bytes as base64 or reject visibly.",
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "encoding": {
          "enum": [
            "utf8",
            "base64"
          ]
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "digest": {
          "$ref": "#/$defs/Digest"
        }
      }
    },
    "WorkerArtifactReference": {
      "type": "object",
      "required": [
        "ref"
      ],
      "additionalProperties": false,
      "description": "A Worker report may supply only a service-issued ref for that same granted invocation. Gateway resolves and replaces metadata before the Core report; a reference alone grants no permission.",
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        }
      }
    },
    "SourceUploadPermission": {
      "type": "object",
      "required": [
        "sourceRecordId",
        "permission",
        "upload"
      ],
      "additionalProperties": false,
      "description": "One off-machine upload decision for one actual Source record. Only an explicit granted permission admits Artifact object bytes. Ordinary bounded inline results and facts still leave the machine under the existing Tool and Source disclosure rules; this object-storage permission is neither their authorization nor a bypass of it. denied is a recorded refusal; absent means no permission record was found, including the Source-free case where sourceRecordId is empty, and it must be refused under its own name so that adding, renaming or normalizing a policy key can never turn the refusal into a silent allow. quota and budget are separate and grant nothing.",
      "properties": {
        "sourceRecordId": {
          "type": "string"
        },
        "permission": {
          "enum": [
            "granted",
            "denied",
            "absent"
          ]
        },
        "upload": {
          "type": "boolean"
        },
        "refusal": {
          "anyOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "type": "null"
            }
          ],
          "description": "The refusal identity the producing implementation must return when upload is false, and null when it is true. Naming the refusal is the point; a refusal that reads as an unconfigured lookup cannot be told apart from a missing rule."
        }
      }
    },
    "ReceiptArtifact": {
      "type": "object",
      "required": [
        "ref",
        "mediaType",
        "totalBytes",
        "digest"
      ],
      "additionalProperties": false,
      "description": "Protected Gateway-to-Core report metadata, resolved from an already durably retained object. Core commits the reference with its execution receipt; ExecutionResultVector carries this array into resultDigest. Worker self-authored metadata or cross-invocation/Source reuse is refused, and refusing a forged cross-invocation report never releases the retain the producing invocation legitimately holds. Because this shape has four fields, an array uniqueItems constraint over it only bars two identical objects: the same ref carrying two different sets of metadata satisfies uniqueItems and would still change the receipt digest, so uniqueness by ref belongs to the Gateway resolution step and must be refused there by name. An object the Core still references is not collectable, and an object that has not entered a proof may still carry an execution audit reference; return to temporary retention is allowed only once the authority confirms no reference and no pending retain request remains. Physical collection stays deferred, so nothing here starts an automatic sweep.",
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "digest": {
          "$ref": "#/$defs/Digest"
        }
      }
    },
    "Digest": {
      "type": "string",
      "pattern": "^sha256:[a-f0-9]{64}$"
    }
  }
}

docs/specs/schemas/rulith-board-observat.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-board-observation-v3.schema.json",
  "title": "Public committed Board observation (rulith/v4)",
  "description": "The decoded JSON text of a new QueryBoard tool result, not a Core command or MCP structuredContent declaration. The Gateway preserves the first durably captured view under the authenticated session and RPC identity; a retry reprojects that snapshot under current disclosure permission. QueryBoard is never held and never takes the execution slot. Every result, refusals included, carries the Agent's recent-operations strip, generated when the response is written; the strip is not an atomic observation of external effects at the view's revision, and it may deliver the latest determined result without changing any execution fact. Package A (D-1008i): derived from rulith-board-observation-v2 for rulith/v4. The strip is the v4 strip, and the view speaks of goals; its goal-vocabulary members are described by the descriptive definitions below, which no wire validation references.",
  "$ref": "#/$defs/QueryBoardResult",
  "$defs": {
    "BoardObservation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["consistency"],
      "properties": {
        "consistency": { "const": "committed" }
      }
    },
    "QueryBoardResult": {
      "type": "object",
      "additionalProperties": false,
      "required": ["accepted", "operations"],
      "properties": {
        "accepted": { "type": "boolean" },
        "view": { "type": "object" },
        "observation": { "$ref": "#/$defs/BoardObservation" },
        "errorCode": { "type": "string", "minLength": 1 },
        "teaching": { "type": "string" },
        "requestExecuted": { "const": false },
        "operations": { "$ref": "rulith-agent-mcp-meta-v4.schema.json#/$defs/OperationsStrip" }
      },
      "allOf": [
        {
          "if": { "properties": { "accepted": { "const": true } }, "required": ["accepted"] },
          "then": { "required": ["view", "observation"], "not": { "required": ["requestExecuted"] } },
          "else": { "required": ["errorCode"] }
        },
        {
          "if": { "properties": { "errorCode": { "$ref": "rulith-agent-mcp-meta-v4.schema.json#/$defs/DisclosureRefusalCode" } }, "required": ["errorCode"] },
          "then": { "not": { "required": ["view"] } },
          "else": {
            "if": { "properties": { "accepted": { "const": false } }, "required": ["accepted"] },
            "then": { "required": ["view", "requestExecuted"] }
          }
        }
      ],
      "description": "view retains the existing authorized Agent QueryBoard projection and bounds, in the goal vocabulary of package A (AgentGoalView). A refusal carries the strip. A refusal about disclosure or read authorization carries no view; any other refusal was not executed and carries requestExecuted:false and the bounded view of the current position. This schema is not an authorization filter; no error implies anything about the original business effect."
    },
    "AgentGoalView": {
      "type": "object",
      "properties": {
        "goals": { "$ref": "#/$defs/AgentGoalDirectory" },
        "goalTypes": { "type": "array", "items": { "$ref": "#/$defs/AgentGoalTypeRow" } },
        "taskStatus": { "type": "array", "items": { "$ref": "#/$defs/AgentTaskStatusRow" } },
        "history": { "$ref": "#/$defs/AgentHistoryPage" },
        "goalNodes": { "type": "array", "items": { "type": "object" }, "description": "Goal-node rows of a nodes read (view.goals[] before package A)." },
        "facts": { "type": "array", "items": { "$ref": "#/$defs/AgentFactRow" } }
      },
      "not": { "anyOf": [ { "required": ["cases"] }, { "required": ["caseTypes"] }, { "required": ["caseHistory"] } ] },
      "description": "Descriptive (package A, D-1008i), referenced by no wire validation: QueryBoardResult.view stays a free object, as D-1003a fixed for the position shapes; fixtures and implementation tests check shapes against it. It names the members of the Agent audience Board View that package A rewrote in goal vocabulary: goals replaces cases (A-17), goalTypes replaces caseTypes (A-18), taskStatus rows are keyed by goal (A-20) and history replaces caseHistory (A-19). position (Board schema AgentPosition, with newGoals and goals_expired), actions (AgentActionState, with goal_paused and goal_ended) and the other members keep their v3 shape. The v3 members cases, caseTypes and caseHistory never appear. view.goals is the goal directory; the goal-node rows a nodes read listed as view.goals[] before package A are view.goalNodes[] (same rows, goalNodes[].actionHints included)."
    },
    "AgentGoalDirectory": {
      "type": "object",
      "required": ["directory"],
      "properties": {
        "directory": { "type": "array", "items": { "$ref": "#/$defs/AgentGoalDirectoryRow" } },
        "total": { "type": "integer", "minimum": 0, "maximum": 9007199254740991 },
        "truncated": { "const": true }
      },
      "description": "Package A (D-1008i), A-17: view.goals, the bounded directory of open and recently ended top-level goals, replacing view.cases. It keeps the v3 directory's limit, total and truncation self-description; no Case identity appears."
    },
    "AgentGoalDirectoryRow": {
      "type": "object",
      "additionalProperties": false,
      "required": ["goal", "label", "status"],
      "properties": {
        "goal": { "type": "string", "minLength": 1 },
        "label": { "type": "string", "minLength": 1 },
        "status": { "enum": ["running", "paused", "completed", "ended"] },
        "type": { "type": "string", "minLength": 1 },
        "deadline": { "const": "elapsed" },
        "awaiting": { "enum": ["decision", "sign_off"], "description": "sign_off is historical only (D-1013a), retained to decode stored results; new results only use decision." },
        "seat": { "$ref": "rulith-agent-mcp-meta-v4.schema.json#/$defs/SeatName", "description": "Historical only (D-1013a): optional in stored results; not emitted by new projections, including history rows." },
        "heldBy": { "enum": [["operator"], ["policy"], ["operator", "policy"]] }
      },
      "allOf": [
        {
          "if": { "properties": { "status": { "const": "running" } } },
          "else": { "not": { "required": ["deadline"] } }
        },
        {
          "if": { "properties": { "status": { "const": "paused" } } },
          "else": { "not": { "required": ["heldBy"] } }
        }
      ],
      "description": "Package A (D-1008i), A-17: one top-level goal, {goal, label, status, type?, deadline?, awaiting?, seat?}. type is the terminal predicate of a capability goal type and is omitted for exploration goals. deadline \"elapsed\" appears only on a running goal past its deadline. awaiting is \"decision\" or \"sign_off\". seat is historical only (D-1013a), retained to decode stored goal provenance and not emitted in new results. heldBy keeps its v3 meaning on paused goals (package A does not retire it)."
    },
    "AgentGoalTypeRow": {
      "type": "object",
      "additionalProperties": false,
      "required": ["goal"],
      "properties": {
        "goal": { "type": "string", "minLength": 3, "maxLength": 512, "pattern": "^[A-Za-z_][A-Za-z0-9_.]*\\([A-Za-z0-9_, ]*\\)$" },
        "status": { "const": "pending" }
      },
      "description": "Package A (D-1008i), A-18: view.goalTypes[] replaces view.caseTypes[]. One capability goal type this Agent can declare, written as its terminal predicate with its key arguments, \"<predicate>(<key>, …)\". status \"pending\" means configured but not in effect yet, by the same judgement as declaration admission; otherwise it is omitted. Exploration has no row: any goal declared without parent that is not a capability goal is exploration."
    },
    "AgentTaskStatusRow": {
      "type": "object",
      "required": ["goal"],
      "properties": {
        "goal": { "type": "string", "minLength": 1 },
        "certified": { "type": "boolean" },
        "awaiting": { "enum": ["decision", "sign_off"], "description": "sign_off is historical only (D-1013a), retained to decode stored results; new results only use decision." }
      },
      "not": { "anyOf": [ { "required": ["root"] }, { "required": ["close"] } ] },
      "description": "Package A (D-1008i), A-20: a taskStatus row for one goal named in selector.goals, keyed by goal instead of root. It has no close member, because the Agent no longer requests completion. certified, floor, frontier, leaves, gaps, blocked, awaiting and the other members keep their v3 meaning; an unavailable goal gives a row with that status and nothing more."
    },
    "AgentHistoryPage": {
      "type": "object",
      "required": ["goal", "status"],
      "properties": {
        "goal": { "type": "string", "minLength": 1 },
        "status": { "enum": ["available", "unavailable"] },
        "type": { "type": "string", "minLength": 1 }
      },
      "not": { "anyOf": [ { "required": ["root"] }, { "required": ["caseId"] }, { "required": ["caseType"] }, { "required": ["historyVersion"] } ] },
      "description": "Package A (D-1008i): view.history replaces view.caseHistory, answering include:[\"history\"] with exactly one selector.goals entry. It is keyed by goal instead of root, names a capability goal's type as type instead of caseType, and carries no Case identity. Its status, disposition, certified, receipt and proof boundaries, facts and paging members (total, offset, nextOffset, truncated) keep their v3 meaning; D-1012a: it carries no historyVersion, and a later page continues from nextOffset alone. It is history, not the current Board, and carries no position."
    },
    "AgentFactRow": {
      "type": "object",
      "required": ["nodeId"],
      "properties": {
        "nodeId": { "type": "string", "minLength": 1 },
        "createdBy": { "type": "string", "minLength": 1 },
        "derived": { "type": "boolean" },
        "seat": { "$ref": "rulith-agent-mcp-meta-v4.schema.json#/$defs/SeatName", "description": "Historical only (D-1013a): optional in stored results; not emitted by new projections, including history rows." }
      },
      "description": "A fact row of the Agent audience view; package A does not change it. seat is historical only (D-1013a), retained to decode stored fact provenance and not emitted in new results or new history projections. createdBy \"tool\", derived: true and createdBy \"agent\" keep the meaning the QueryBoard input description teaches."
    }
  }
}

docs/specs/schemas/rulith-board-query-co.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-board-query-context-v1.schema.json",
  "title": "Protected QueryBoard context",
  "description": "Set by Gateway from authenticated request context, never accepted as Agent tool input. Core validates audience against authenticated principal before reading nodes. Audience enum is checked against QueryBoard.audienceProfiles in operations.json.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "audienceProfile"
  ],
  "properties": {
    "audienceProfile": {
      "type": "string",
      "enum": [
        "agent",
        "operator",
        "internal"
      ]
    },
    "requestedRoots": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "Acceptance-root ids, not case ids. Omitted or [] requests no additional root summaries; this never supplies an Agent selector.roots prerequisite."
    }
  },
  "$defs": {
    "AudienceAllowances": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "principals": {
          "type": "object",
          "additionalProperties": {
            "type": "array",
            "uniqueItems": true,
            "items": {
              "type": "string",
              "enum": [
                "agent",
                "operator",
                "internal"
              ]
            }
          }
        },
        "default": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "const": "agent"
          },
          "description": "Absence means the agent base allowance; operator/internal cannot be granted through a default."
        }
      }
    }
  }
}

docs/specs/schemas/rulith-board-v1.schem.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-board-v1.schema.json",
  "title": "Rulith Board Protocol v1 (rulith-board/1)",
  "description": "Normative artifact promised by protocol-spec section 3. RT-SCHEMA guards keep this Schema, the operation model, documentation, and the Rust advertisement aligned. Every command accepted by protocol conformance fixtures must validate against this Schema. Required fields are the wire-level fields whose absence the authoritative service rejects. Identity is not part of this Schema: principal, roles, and channelId are injected by authenticated transport and never accepted from the request body. The root shape is BoardCommand; responses and events are BoardResult and BoardEvent.",
  "$ref": "#/$defs/BoardCommand",
  "$defs": {
    "BoardCommand": {
      "description": "Command envelope. requestId provides idempotency. There is no caller-supplied concurrency pin: one Board holds one shared graph, a write is judged against the premises current at execution time, and which acceptance roots it reached is answered afterwards in BoardResult.affectedCases rather than declared beforehand. queryContext and admission are set by the Gateway from the authenticated request and are never accepted as model input. The envelope remains open for backward-compatible field additions, while each operation shape remains closed; the retired names listed in retiredEnvelopeFields are the exception, and they are refused rather than ignored.",
      "type": "object",
      "required": [
        "protocol",
        "boardId",
        "requestId",
        "operation"
      ],
      "additionalProperties": true,
      "allOf": [
        {
          "$ref": "#/$defs/RetiredEnvelopeFields"
        },
        {
          "$ref": "#/$defs/QueryContextRequiredForQueryBoard"
        },
        {
          "$ref": "#/$defs/AdmissionRequiredForOpenCaseCreate"
        }
      ],
      "properties": {
        "protocol": {
          "const": "rulith-board/1"
        },
        "locale": {
          "type": "string",
          "enum": [
            "en"
          ],
          "description": "Presentation language for this response. It affects teaching and presentation only and never enters closure, revision, or idempotency identity. Omitted means en. Any other value is rejected with bad_command; GetProtocolManifest.locales advertises the supported set."
        },
        "boardId": {
          "type": "string",
          "minLength": 1
        },
        "requestId": {
          "type": "string",
          "minLength": 1
        },
        "queryContext": {
          "$ref": "rulith-board-query-context-v1.schema.json",
          "description": "Protected read context, injected by the Gateway from the authenticated request. Referenced, never restated: the audience enum and the requestedRoots shape have one normative home, and a second copy here would be a second thing to keep in step. A network QueryBoard without it is refused before any node is read (audience_profile_required)."
        },
        "admission": {
          "$ref": "#/$defs/CaseAdmission",
          "description": "Gateway-authorized Case admission, injected from the authenticated request. Required on the OpenCase create form and ignored elsewhere; a create without it is refused."
        },
        "goalAdmissions": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "op"
            ],
            "oneOf": [
              {
                "required": [
                  "admission"
                ],
                "not": {
                  "required": [
                    "unfunded"
                  ]
                }
              },
              {
                "required": [
                  "unfunded"
                ],
                "not": {
                  "anyOf": [
                    {
                      "required": [
                        "admission"
                      ]
                    },
                    {
                      "required": [
                        "caseClosure"
                      ]
                    }
                  ]
                }
              }
            ],
            "properties": {
              "op": {
                "type": "integer",
                "minimum": 0,
                "description": "Index, in this ApplyBatch's operations, of the declare_goal without parent that this admission opens."
              },
              "admission": {
                "$ref": "#/$defs/CaseAdmission"
              },
              "unfunded": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "caseType",
                  "code",
                  "teaching"
                ],
                "properties": {
                  "caseType": {
                    "type": "string",
                    "minLength": 1
                  },
                  "businessKeyDigest": {
                    "type": "string",
                    "minLength": 1
                  },
                  "code": {
                    "type": "string",
                    "minLength": 1
                  },
                  "teaching": {
                    "type": "string",
                    "minLength": 1
                  }
                },
                "description": "Erratum D-1009c: the Gateway could not fund this declaration (quota, pending limit, inactive Release, authorization). It sends the goal identity (caseType, and businessKeyDigest for a capability goal only) and the refusal it would have given. The Core returns the existing goal with opened:false when that identity is open or declared earlier in the batch, and refuses the whole batch with this refusal, zero writes, only when the declaration would open a new Case (A-6)."
              },
              "caseClosure": {
                "$ref": "#/$defs/CloseCase/properties/caseClosure",
                "description": "Erratum D-1009c: the governance-frozen closure envelope of this goal's contract, frozen at declaration so that the Core can certify and complete the goal by itself (A-13) with the same closure CloseCase used. Injected by the Gateway; never authored by the model."
              }
            }
          },
          "description": "Package A (D-1008i). Gateway-authorized admissions for the top-level goals an ApplyBatch declares, injected from the authenticated request, one per such declare_goal. The Core opens each Case in the batch transaction; a top-level declare_goal without its admission is refused with zero writes. Ignored on other operations."
        },
        "seat": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9_-]{0,31}$",
          "description": "Historical only (D-1013a): optional stored command seat provenance; not injected into new commands. Original envelopes and results remain readable without rewriting."
        },
        "operation": {
          "$ref": "#/$defs/BoardOperation"
        }
      }
    },
    "CaseAdmission": {
      "description": "Commercial, Capability and program pins authorized before a Case is created. businessKeyDigest is required but nullable: null means a non-keyed exploration Case; absence is a missing commitment and is refused. A new creation also requires expectedProgramGeneration; its omission remains decodable only to retrieve a historical committed request's original receipt. Wrong-typed values are refused rather than coerced. Affinity is optional.",
      "type": "object",
      "required": [
        "capabilityReleaseDigest",
        "caseContractDigest",
        "businessKeyDigest",
        "commercialTermsDigest",
        "maxExplorationBps"
      ],
      "additionalProperties": false,
      "properties": {
        "expectedProgramGeneration": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991,
          "description": "Required to create a new Case: the active program generation observed before authorizing and reserving this admission. A mismatch refuses without minting identity. Omission can only return a previously committed historical request's original receipt, never create a new root."
        },
        "capabilityReleaseDigest": {
          "type": "string",
          "minLength": 1
        },
        "caseContractDigest": {
          "type": "string",
          "minLength": 1
        },
        "businessKeyDigest": {
          "type": [
            "string",
            "null"
          ],
          "description": "sha256 of the frozen business key, or an explicit null for a non-keyed exploration Case. Omitting the field is not the same as sending null and is refused."
        },
        "commercialTermsDigest": {
          "type": "string",
          "minLength": 1
        },
        "maxExplorationBps": {
          "type": "integer",
          "minimum": 0,
          "maximum": 65535,
          "description": "Wire domain is the u16 the authority parses into. The platform profile refuses anything above 1000 at OpenCase, with teaching; that is a policy ceiling and lives there, not in this type."
        },
        "affinityKey": {
          "type": "string",
          "minLength": 1,
          "description": "Optional routing hint. Absent means no affinity was requested."
        },
        "versionedInput": {
          "description": "Optional Host-selected /2 opening. It is injected with authenticated admission, never supplied in the model OpenCase operation. The Core must still check this fact and its current Source binding in the same opening transaction; schema validation alone grants no authority.",
          "type": "object",
          "additionalProperties": false,
          "required": [
            "contract",
            "openingFactId"
          ],
          "properties": {
            "contract": {
              "$ref": "rulith-case-contract-v2.schema.json"
            },
            "openingFactId": {
              "type": "string",
              "pattern": "^obs_[0-9a-f]{32}_[0-9]+$"
            }
          }
        },
        "taskTemplate": {
          "description": "PSC 0.2.5 PROPOSED (D-1003b). Host-only frozen template contract, selected from the owning active Release. Core verifies all pins and binds trusted opening data atomically; omission cannot downgrade a templated contract to bare creation. Never model input.",
          "type": "object",
          "additionalProperties": false,
          "required": ["contract"],
          "properties": {
            "contract": {
              "allOf": [
                { "oneOf": [{ "$ref": "rulith-case-contract-v1.schema.json" }, { "$ref": "rulith-case-contract-v2.schema.json" }] },
                { "type": "object", "required": ["taskTemplate"] }
              ]
            }
          }
        }
      },
      "allOf": [{
        "if": {
          "type": "object", "required": ["taskTemplate"],
          "properties": { "taskTemplate": {
            "type": "object", "required": ["contract"],
            "properties": { "contract": {
              "type": "object", "required": ["format"],
              "properties": { "format": { "const": "rulith-case-contract/2" } }
            } }
          } }
        },
        "then": { "type": "object", "required": ["versionedInput"] }
      }, {
        "if": {
          "type": "object", "required": ["versionedInput"],
          "properties": { "versionedInput": {
            "type": "object", "required": ["contract"],
            "properties": { "contract": { "type": "object", "required": ["taskTemplate"] } }
          } }
        },
        "then": { "type": "object", "required": ["taskTemplate"] }
      }]
    },
    "RetiredEnvelopeFields": {
      "description": "The envelope keys the authority refuses **by name**, listed here so this Schema refuses them too. Without this the envelope's additionalProperties:true would let every one of them validate, and a client generating requests from this artifact would keep sending a field the service rejects while the contract said it was fine. Ignoring them is the worst available behaviour and is why the authority refuses instead: a caller that sent case:{...} believes it scoped the command to one Case, and answering against the whole shared graph would be the widest possible read reported as a success; a caller that sent viewToken believes a freshness check ran. case, caseRevision and expectedRevision are gone with the per-Case namespace and its compare-and-set pin; viewToken and interaction.bootstrap are gone with the observation cursor. None has a replacement field — affectedCases answers the membership question afterwards. Other unknown keys stay permitted: this list closes exactly the names the authority closes, and closing more would be a rule nothing enforces.",
