    "AgentPreparedStep": {
      "description": "Package A (D-1008i), formerly AgentPreparedTaskNode {node, goal}: one step a capability's template planted under a newly declared capability goal. goal is the step's goal ID, already disclosed in the view; label is its template label.",
      "type": "object",
