    "AgentDeclaredGoal": {
      "description": "Package A (D-1008i). One entry of result.goals in a successful ApplyBatch, one per declare_goal operation in declaration order (A-9). goal is the declared goal's ID. opened is true when this call created the goal; false when the declaration returned a goal with the same identity that was already open, or declared earlier in the same batch (A-6). children and vocabulary keep the rules of the former AgentOpenCaseResult taskNodes and vocabulary (D-1004b, D-1008c): they appear only when this call newly opened a capability goal, and on that response's original replay; never for opened:false, exploration goals, sub-goals or refusals. Never recompute or replant on replay; when the current disclosure re-check fails, omit the whole field rather than assembling another list.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "goal",
        "opened"
      ],
      "properties": {
        "goal": {
          "type": "string",
          "minLength": 1
        },
        "opened": {
          "type": "boolean"
        },
        "children": {
          "description": "（A 包，D-1008i）模板种下的里程碑，按冻结的模板顺序，带已在视图中披露的原 ID 与标签。本版模板最多 16 叶，低于默认 500 行限额，不会截断，因此没有截断字段。",
          "type": "array",
          "minItems": 1,
          "maxItems": 16,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/AgentPreparedStep"
          }
        },
        "vocabulary": {
          "description": "D-1008c（A 包沿用）：该能力目标所属能力程序定义的谓词签名，name(arg, …)，按声明顺序，不含结构谓词；至多 32 项、合计 4 KiB，超出时 vocabularyTruncated 为 true。",
          "type": "array",
          "minItems": 1,
          "maxItems": 32,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 3,
            "maxLength": 512,
            "pattern": "^[A-Za-z_][A-Za-z0-9_.]*\\([A-Za-z0-9_, ]*\\)$"
          }
        },
        "vocabularyTruncated": {
          "description": "D-1008c（A 包沿用）：vocabulary 因 32 项或 4 KiB 的上限未列全时为 true。",
          "const": true
        }
      },
      "dependencies": {
        "vocabularyTruncated": [
          "vocabulary"
        ]
      },
      "if": {
        "properties": {
          "opened": {
            "const": false
          }
        }
      },
      "then": {
        "not": {
          "anyOf": [
            {
              "required": [
                "children"
              ]
            },
            {
              "required": [
                "vocabulary"
              ]
            }
          ]
        }
      }
    },
    "AgentApplyBatchResult": {
      "description": "PSC 0.2.5 PROPOSED (D-1004b). Descriptive successful inner ApplyBatch result. Existing payload members remain possible. warnings never changes a committed write: retain existing execution/rule-quality warnings, then ownership-filter warnings, then inert-predicate warnings in assertion order, once per predicate. Preserve the original warnings on replay; re-check disclosure, do not re-evaluate against current programs or readers. Package A (D-1008i): goals lists every declare_goal of the batch in declaration order and is omitted when the batch declares none; nodeIds is unchanged.",
      "type": "object",
      "required": [
        "nodeIds",
        "warnings"
      ],
      "properties": {
        "nodeIds": {
          "type": "array",
          "maxItems": 500,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "warnings": {
          "type": "array",
          "maxItems": 500,
          "items": {
            "type": "string"
          }
        },
        "goals": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/AgentDeclaredGoal"
          }
        },
        "nodeIdsTruncated": {
          "$ref": "#/$defs/AgentResultListTruncation"
        },
        "warningsTruncated": {
          "$ref": "#/$defs/AgentResultListTruncation"
        }
      }
    },
    "AgentEndGoalResult": {
      "description": "Package A (D-1008i); D-1012a: the end_goal batch operation dispatches to the private Core operation EndGoal. Descriptive successful inner EndGoal result (V44), not a Core envelope or a new wire validator: the goal and the non-completed disposition it ended with. It carries no Case identity and no terminal receipt; those stay Host, receipt and Console material. Completion is never an EndGoal result: the goal directory shows it as status \"completed\".",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "goal",
        "disposition"
      ],
      "properties": {
        "goal": {
          "type": "string",
          "minLength": 1
        },
        "disposition": {
          "$ref": "#/$defs/wm_end_goal/properties/disposition"
        }
      }
    }
  }
}

protocol/mcp-surface.json.content:
{
  "schema": "rulith-mcp-surface/v4",
  "protocolVersion": "2025-11-25",
  "description": "Public Agent tool membership and dispatch (package A, D-1008i): three tools and no operation-read tool (D-1012g). OpenCase and CloseCase have left the model surface; a declare_goal without parent starts new work inside Set, and the ApplyBatch operation end_goal, alone in its batch, dispatches to the private Core operation EndGoal with a non-completed disposition only. The Gateway holds each call until its outcome, a human decision or the hold bound, and every tool result carries the Agent's recent-operations strip defined by the v4 metadata schema. Its existence does not attest that a running server has adopted it. Historical v1, v2 and v3 bundles remain verifiable against their Git commits but cannot be adopted as this v4 surface. schemaRef values identify files from the Core repository root; vendors verify a source-path-to-bytes map against the named Git commit and resolve it without network access. Adopting Gateways serve each inputSchema directly from the verified rulith-mcp-contract-bundle/v1 tools entry, including its generated definition names and explicit dialect. Object key order and JSON whitespace are immaterial; independently regenerated schema shapes are not the delivered contract.",
  "metadata": {
    "namespace": "rulith/v4",
    "schemaRef": "docs/specs/schemas/rulith-agent-mcp-meta-v4.schema.json"
  },
  "tools": [
    {
      "name": "Get",
      "target": "core",
      "operation": "QueryBoard",
      "inputSchemaRef": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/AgentGet",
      "resultSchemaRef": "docs/specs/schemas/rulith-board-observation-v3.schema.json#/$defs/QueryBoardResult",
      "artifactRoute": {
        "argument": "artifact",
        "target": "artifact",
        "operation": "ReadArtifact",
        "resultSchemaRef": "docs/specs/schemas/rulith-artifact-read-v1.schema.json#/$defs/ReadArtifactResult"
      }
    },
    {
      "name": "Set",
      "target": "core",
      "operation": "ApplyBatch",
      "inputSchemaRef": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/AgentSet"
    },
    {
      "name": "Execute",
      "target": "core",
      "operation": "ApplyAction",
      "inputSchemaRef": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/AgentExecute"
    }
  ]
}

