        "outboxId": "bout_0123456789abcdef0123456789abcdef",
        "terminalReceiptDigest": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        "usageDigest": "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
      },
      "note": "Authenticated governance/billing control-plane append-only acknowledgement. It binds the immutable item by outbox id, terminal receipt digest, and usage digest and never deletes the item."
    },
    {
      "kind": "RunDischarge",
      "write": true,
      "required": [],
      "manifest": [],
      "sample": {
        "kind": "RunDischarge"
      },
      "note": "The advertised surface also applies the runtime can_discharge predicate; this static table defines membership only."
    },
    {
      "kind": "ApplyBatch",
      "agentVerb": true,
      "write": true,
      "required": [
        [
          "operations",
          "a"
        ]
      ],
      "manifest": [
